import type { CardOperationContext } from './card_operation_context'
import { setCardHeaderFields, setCardTitle } from './card_mutations'
import { markdownParsingService } from './markdown_parsing_service'

/**
 * Card title edits and the file renames they trigger. Renames are serialized per card and
 * flushed on their own so a move never shares a commit batch entry with another edit.
 */
export class CardRenameOperations {
    private readonly context: CardOperationContext
    /** Tracks where renamed cards landed so queued title updates keep targeting the same card. */
    private readonly committedPathsByPath = new Map<string, string>()
    private readonly renameChainByPath = new Map<string, Promise<void>>()

    constructor(context: CardOperationContext) {
        this.context = context
    }

    /** Drops rename tracking that only applies to the previously open project. */
    reset() {
        this.committedPathsByPath.clear()
    }

    /** Saves the new title and, when it changes the card file name, renames the file. */
    async updateCardTitle(path: string, title: string, saveReference?: OpenDocumentSaveReference) {
        return this.queueRename(path, (currentPath) => this.applyCardTitle(currentPath, title, saveReference))
    }

    /** Changes a card id and path to the next number for the selected configured type. */
    async updateCardType(path: string, type: CardType, saveReference?: OpenDocumentSaveReference) {
        return this.queueRename(path, (currentPath) => this.applyCardType(currentPath, type, saveReference))
    }

    private queueRename(path: string, applyRename: (currentPath: string) => Promise<MarkdownFile> | MarkdownFile) {
        const pending = this.renameChainByPath.get(path) ?? Promise.resolve()
        const renameUpdate = pending.then(
            () => applyRename(this.committedPath(path)),
            () => applyRename(this.committedPath(path)),
        )
        const chained = renameUpdate.then(() => undefined, () => undefined)
        this.renameChainByPath.set(path, chained)
        void chained.then(() => {
            if (this.renameChainByPath.get(path) === chained) this.renameChainByPath.delete(path)
        })

        return renameUpdate
    }

    private async applyCardTitle(path: string, title: string, saveReference?: OpenDocumentSaveReference) {
        const { dependencies } = this.context
        const snapshot = dependencies.snapshot()
        const occupiedPaths = [
            ...dependencies.files().map((currentFile) => currentFile.path),
            ...(snapshot?.repositoryFiles ?? []),
        ]
        const targetPath = desiredCardPath(path, title, occupiedPaths)
        if (targetPath === path) {
            const card = this.context.saveCardChange(path, (currentCard) => setCardTitle(currentCard, title), saveReference)

            return markdownParsingService.serializeCard(card)
        }

        return this.renameCard(path, targetPath, (card) => setCardTitle(card, title), saveReference)
    }

    private async applyCardType(path: string, type: CardType, saveReference?: OpenDocumentSaveReference) {
        const { dependencies } = this.context
        const { config } = dependencies.requireDependencies()
        const cardType = config.cardTypes.find((candidate) => candidate.type === type)
        if (!cardType) throw new Error(`Unknown card type: ${type}`)

        const card = dependencies.requireCard(path)
        if (getCardIdPrefix(card.header.id) === cardType.idPrefix) return markdownParsingService.serializeCard(card)

        const number = getNextCardNumber(dependencies.files(), cardType.idPrefix)
        const id = buildCardId(cardType.idPrefix, number, config.cardSeparator)
        const targetPath = cardPathForId(path, id, card.header.title, config.cardSeparator)
        this.context.requireAvailablePath(targetPath)
        return this.renameCard(path, targetPath, (currentCard) => setCardHeaderFields(currentCard, { id }), saveReference)
    }

    /** Commits pending work, then commits the rename on its own so no other change shares its batch entry. */
    private async renameCard(
        path: string,
        targetPath: string,
        mutation: (card: Card) => void,
        saveReference?: OpenDocumentSaveReference,
    ) {
        const { dependencies } = this.context
        const { commitBatcher, config, project } = this.context.requireProject('rename a card')

        await this.context.flushPendingCommits()

        const card = this.context.mutateCardPreservingOpenBody(path, mutation, config.workingFolder)
        const cardInternalId = card.header.internalId
        if (!cardInternalId) throw new Error(`Cannot rename a card without an internal ID: ${path}`)
        const documentSaveReference = saveReference ?? this.context.findOpenCardDocument(path)?.createSaveReference()
        commitBatcher.schedulePathChange(
            project.branch,
            { cardInternalId, kind: 'card', path, saveReference: documentSaveReference, targetPath },
            `Rename ${path} to ${targetPath}`,
            (fromPath, toPath) => this.reconcileCardPath(fromPath, toPath),
        )
        dependencies.dispatchChanged()
        await this.context.flushPendingCommits()

        return markdownParsingService.serializeCard(card)
    }

    /** Moves local state onto the committed path and lets path-keyed callers follow the card. */
    private reconcileCardPath(fromPath: string, toPath: string) {
        if (fromPath === toPath) return

        const { dependencies } = this.context
        const { config } = dependencies.requireDependencies()
        dependencies.renameFile(fromPath, toPath, config.workingFolder)
        for (const [sourcePath, currentPath] of this.committedPathsByPath) {
            if (currentPath === fromPath) this.committedPathsByPath.set(sourcePath, toPath)
        }
        this.committedPathsByPath.set(fromPath, toPath)
        dependencies.cardPathChanged(fromPath, toPath)
        dependencies.dispatchChanged()
    }

    private committedPath(path: string) {
        return this.committedPathsByPath.get(path) ?? path
    }
}

import { orderByAfter, statusOf } from '../../data/card_ordering'
import type { MarkdownFile } from '../../data/data_types'
import { newFolderPath, newMarkdownFilePath } from '../../data/project_tree_paths'
import type { CardOperationContext } from './card_operation_context'
import { markdownParsingService } from './markdown_parsing_service'
import { setCardHeaderFields } from './card_mutations'

const FOLDER_PLACEHOLDER_NAME = '.gitkeep'

/** Creating, saving and deleting plain project files and folders outside the card workflow. */
export class ProjectFileOperations {
    private readonly context: CardOperationContext

    constructor(context: CardOperationContext) {
        this.context = context
    }

    async createFolder(parentDirectory: string, name: string) {
        const { config, project, storage } = this.context.requireProject('create a folder')

        const folderPath = newFolderPath(parentDirectory, name, config.projectFolder)
        this.context.requireAvailablePath(folderPath)
        await storage.commit({
            branch: project.branch,
            files: [{ content: '', path: `${folderPath}/${FOLDER_PLACEHOLDER_NAME}` }],
            message: `Create ${folderPath}`,
        })
        await this.context.pushCreatedItem('Folder')
        this.context.dependencies.addRepositoryFile(`${folderPath}/${FOLDER_PLACEHOLDER_NAME}`)
        this.context.dependencies.dispatchChanged()

        return folderPath
    }

    async createMarkdownFile(parentDirectory: string, name: string) {
        const { config, project } = this.context.requireProject('create a Markdown file')

        const path = newMarkdownFilePath(parentDirectory, name, config.projectFolder)
        this.context.requireAvailablePath(path)
        const file = { content: '', path }
        await this.context.commitAndMergeFiles({
            branch: project.branch,
            files: [file],
            message: `Create ${path}`,
        }, [file])
        await this.context.pushCreatedItem('Markdown file')

        return file
    }

    async saveProjectFile(file: MarkdownFile, message: string) {
        const { config, project, storage } = this.context.requireProject('save a project file')

        await this.context.commitAndMergeFiles({ branch: project.branch, files: [file], message }, [file])

        if (config.pushMode === 'auto') await storage.push(project)

        return file
    }

    async deleteFolder(path: string) {
        const { config, project, storage } = this.context.requireProject('delete a folder')

        const folderPrefix = `${path.replace(/\/+$/u, '')}/`
        const repositoryFiles = this.context.dependencies.snapshot()?.repositoryFiles ?? []
        if (!repositoryFiles.some((filePath) => filePath.startsWith(folderPrefix))) {
            throw new Error(`Cannot delete a folder that is not loaded: ${path}`)
        }

        await this.context.flushPendingCommits()
        await storage.deleteFolder({ branch: project.branch, message: `Delete ${path}`, path })
        if (config.pushMode === 'auto') await storage.push(project)
        this.context.dependencies.removeFolder(path, config.workingFolder)
        this.context.dependencies.dispatchChanged()

        return this.context.dependencies.snapshot()
    }

    /** Deletes a file, first repairing the `after` chain when an ordered active card leaves the board. */
    async deleteProjectFile(path: string, repairActiveOrdering: boolean) {
        const { dependencies } = this.context
        const { config, project, storage } = this.context.requireProject('delete a file')

        await this.context.flushPendingCommits()

        const existingFile = dependencies.files().find((file) => file.path === path)
        const repairFile = repairActiveOrdering ? this.createDeleteRepairFile(path) : null
        let committedRepairFiles: MarkdownFile[] = []

        if (repairFile) {
            committedRepairFiles = await storage.commit({
                branch: project.branch,
                files: [repairFile],
                message: `Repair ordering after deleting ${path}`,
            })
        }

        await storage.deleteFile({
            branch: project.branch,
            message: `Delete ${path}`,
            path,
            ...(existingFile?.sha ? { sha: existingFile.sha } : {}),
        })

        if (config.pushMode === 'auto') await storage.push(project)

        if (repairFile && committedRepairFiles.length === 0) committedRepairFiles = [repairFile]
        dependencies.deleteFile(path, committedRepairFiles, config.workingFolder)
        dependencies.reconcileDeletedActionFile(path)
        dependencies.dispatchChanged()

        return dependencies.snapshot()
    }

    /** Relinks the follower of a deleted card onto the deleted card's predecessor. */
    private createDeleteRepairFile(path: string): MarkdownFile | null {
        const activeCards = this.context.dependencies.snapshot()?.activeCards ?? []
        const deletedCard = activeCards.find((card) => card.path === path)
        if (!deletedCard?.header.internalId) return null

        const column = orderByAfter(activeCards.filter((card) => statusOf(card) === statusOf(deletedCard)))
        const deletedIndex = column.findIndex((card) => card.path === path)
        const follower = column[deletedIndex + 1]
        if (!follower || follower.header.after !== deletedCard.header.internalId) return null

        const { config } = this.context.dependencies.requireDependencies()
        const followerCard = this.context.dependencies.mutateCard(
            follower.path,
            (card) => setCardHeaderFields(card, { after: deletedCard.header.after ?? '' }),
            config.workingFolder,
        )

        return markdownParsingService.serializeCard(followerCard)
    }
}

import { markdownParsingService } from '../services/data/markdown_parsing_service'
import type { CardDraft, CardTypeConfig, MarkdownFile } from './data_types'
import { buildCardId, type CardSeparator } from './card_identifiers'

const MARKDOWN_EXTENSION = '.md'
const DEFAULT_TITLE_SLUG = 'untitled'

function escapeRegExp(value: string) {
    return value.replace(/[.*+?^${}()|[\]\\]/gu, '\\$&')
}

export function slugifyTitle(title: string, cardSeparator: CardSeparator) {
    const slug = title
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9]+/gu, cardSeparator)
        .replace(new RegExp(`^[${escapeRegExp(cardSeparator)}]|[${escapeRegExp(cardSeparator)}]$`, 'gu'), '')

    return slug.length > 0 ? slug : DEFAULT_TITLE_SLUG
}

/** Card file names keep their id and the separator style they were created with. */
const CARD_FILE_NAME_PATTERN = /^([A-Za-z][A-Za-z0-9]*)([-_])(\d+)\2(.+)\.md$/u

function splitPath(path: string) {
    const separatorIndex = path.lastIndexOf('/')

    return separatorIndex === -1
        ? { directory: '', fileName: path }
        : { directory: path.slice(0, separatorIndex), fileName: path.slice(separatorIndex + 1) }
}

/** Builds a card path in its current directory from a new id and configured separator. */
export function cardPathForId(currentPath: string, id: string, title: string, cardSeparator: CardSeparator) {
    const normalizedPath = currentPath.replace(/\\/gu, '/')
    const { directory } = splitPath(normalizedPath)
    const fileName = `${id}${cardSeparator}${slugifyTitle(title, cardSeparator)}${MARKDOWN_EXTENSION}`

    return directory.length > 0 ? `${directory}/${fileName}` : fileName
}

/**
 * Resolves the file path a card should live at for `title`, keeping its id, folder and separator style.
 * Returns `currentPath` when the name cannot be parsed as a card file or the target is already taken.
 */
export function desiredCardPath(currentPath: string, title: string, occupiedPaths: Iterable<string>) {
    const normalizedPath = currentPath.replace(/\\/gu, '/')
    const { directory, fileName } = splitPath(normalizedPath)
    const match = fileName.match(CARD_FILE_NAME_PATTERN)
    if (!match) return currentPath

    const [, idPrefix, separator, number] = match
    const cardSeparator = separator as CardSeparator
    const titleSlug = slugifyTitle(title, cardSeparator)
    const nextFileName = `${idPrefix}${separator}${number}${separator}${titleSlug}${MARKDOWN_EXTENSION}`
    const desiredPath = directory.length > 0 ? `${directory}/${nextFileName}` : nextFileName
    if (desiredPath === normalizedPath) return currentPath

    const sourcePathKey = normalizedPath.toLowerCase()
    const taken = [...occupiedPaths]
        .map((path) => path.replace(/\\/gu, '/').toLowerCase())
        .some((path) => path !== sourcePathKey && path === desiredPath.toLowerCase())

    return taken ? currentPath : desiredPath
}

function getCardTypeConfig(cardTypes: CardTypeConfig[], draft: CardDraft) {
    const cardTypeConfig = cardTypes.find((config) => config.type === draft.type)

    if (!cardTypeConfig) throw new Error(`Missing card type config: ${draft.type}`)

    return cardTypeConfig
}

export function getNextCardNumber(files: MarkdownFile[], idPrefix: string) {
    const idPattern = new RegExp(`(?:^|/)${escapeRegExp(idPrefix)}[-_](\\d+)[-_].+\\.md$`, 'u')
    const numbers = files
        .map((file) => file.path.match(idPattern)?.[1])
        .filter((number): number is string => !!number)
        .map((number) => Number.parseInt(number, 10))

    return numbers.length > 0 ? Math.max(...numbers) + 1 : 1
}

export function createCardFile(
    files: MarkdownFile[],
    workingFolder: string,
    cardSeparator: CardSeparator,
    cardTypes: CardTypeConfig[],
    initialState: string,
    draft: CardDraft,
): MarkdownFile {
    const cardTypeConfig = getCardTypeConfig(cardTypes, draft)
    const number = getNextCardNumber(files, cardTypeConfig.idPrefix)
    const id = buildCardId(cardTypeConfig.idPrefix, number, cardSeparator)
    const titleSlug = slugifyTitle(draft.title, cardSeparator)
    const internalId = markdownParsingService.generateInternalId()
    const content = markdownParsingService.buildCardMarkdown(
        { affects: [], id, internalId, policy: {}, status: initialState, title: draft.title },
        draft.body,
    )

    return {
        content,
        path: `${workingFolder}/${id}${cardSeparator}${titleSlug}${MARKDOWN_EXTENSION}`,
    }
}

